insert into classroom_units (course_id, title, sort_order)
insert into classroom_lessons (unit_id, title, kind, pass_threshold, is_published, sort_order)
insert into classroom_blocks (lesson_id, type, payload, sort_order) values
('<lesson_id>', 'text', replace($blk${"html": "<p><img src=\"@@MEDIA@@shared/hello_rocket.webp\" alt=\"\" style=\"height:200px\"></p><h2>Привет-привет, мастер английского языка 😉</h2><p>Сегодня тебя ждёт новая домашняя работа. Ты точно с ней справишься, можешь быть уверен :) Let's go 😃</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 0),
('<lesson_id>', 'text', replace($blk${"html": "<p>Внизу тебя ждёт видео 👇</p><ol><li>Посмотри его.</li><li>Включи видео ещё раз и найди не обычного человека, а супергероя. Как только его увидишь, попробуй ответить на вопросы: <i>What is he doing? What is he wearing?</i></li></ol>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 1),
('<lesson_id>', 'video', replace($blk${"title": "Посмотри видео и найди супергероя: What is he doing? What is he wearing?", "url": "", "provider": "file"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 2),
('<lesson_id>', 'match', replace($blk${"title": "А теперь давай вспомним, кто что делает. Соедини картинку с предложением", "pairs": [{"left_image": "@@MEDIA@@gg2/u3/cat_sitting.webp", "right": "It is sitting.", "right_audio_tts": "It is sitting."}, {"left_image": "@@MEDIA@@gg2/u3/fox_running.webp", "right": "She is running.", "right_audio_tts": "She is running."}, {"left_image": "@@MEDIA@@gg2/u3/animals_eating.webp", "right": "They are eating.", "right_audio_tts": "They are eating."}, {"left_image": "@@MEDIA@@gg2/u3/animals_reading.webp", "right": "We are reading.", "right_audio_tts": "We are reading."}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 3),
('<lesson_id>', 'quiz', replace($blk${"questions": [{"q": "Mum ___ working today.", "type": "single", "options": [{"text": "am"}, {"text": "is"}, {"text": "are"}], "correct": [1]}, {"q": "They ___ chatting online at the moment.", "type": "single", "options": [{"text": "are"}, {"text": "am"}, {"text": "is"}], "correct": [0]}, {"q": "He ___ taking a photo of a famous person.", "type": "single", "options": [{"text": "am"}, {"text": "are"}, {"text": "is"}], "correct": [2]}, {"q": "We ___ watching a film on TV.", "type": "single", "options": [{"text": "am"}, {"text": "is"}, {"text": "are"}], "correct": [2]}, {"q": "I ___ wearing my tracksuit because we have P.E.", "type": "single", "options": [{"text": "am"}, {"text": "is"}, {"text": "are"}], "correct": [0]}, {"q": "You ___ wearing a nice T-shirt. Is it new?", "type": "single", "options": [{"text": "is"}, {"text": "are"}, {"text": "am"}], "correct": [1]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 4),
('<lesson_id>', 'gaps', replace($blk${"title": "Знакомься! Это Сара. Прочитай про её обычный день и гаджеты, которыми она пользуется. Вставь пропущенные слова", "mode": "drag", "text": "It's a typical day for Sarah. She wakes up and checks her phone. She sees that her friends are __sending__ emails to each other, so she decides to text them too. She quickly gets dressed and heads out to meet her friend, Emma. Emma is __wearing__ a new smartwatch that can do lots of things. They walk to school together, listening to music on their phones. When they arrive at school, the bell rings and they go to class. In class, the teacher is __talking__ about new technologies. Sarah is __watching__ TV on her tablet under the desk, but she still hears what the teacher is __saying__. After class, Sarah and Emma take selfies together with their phones. Later, Sarah's phone rings — it's her mom. Sarah says goodbye to Emma and goes home. At home, Sarah's little brother is __playing__ video games on his computer. After dinner, Sarah watches a movie on her laptop before going to bed. It was a good day, full of new technologies.", "image": "@@MEDIA@@gg2/u3/sarah.webp"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 5),
('<lesson_id>', 'order', replace($blk${"words": ["We", "are", "dancing", "now."], "sentence": "We are dancing now.", "audio_tts": "We are dancing now.", "image": "@@MEDIA@@gg2/u3/bunny_dancing.webp"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 6),
